### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long y1;
    long long y2;
    int rank2;
} Line;

// Comparador para ordenar retas por y1 crescente, e y2 decrescente em empates
static int cmp_lines(const void *a, const void *b) {
    const Line *la = (const Line *)a;
    const Line *lb = (const Line *)b;
    if (la->y1 < lb->y1) return -1;
    if (la->y1 > lb->y1) return 1;
    if (la->y2 > lb->y2) return -1; // decrescente para evitar contar empates em y1
    if (la->y2 < lb->y2) return 1;
    return 0;
}

// Comparador para ordenar ponteiros/valores de y2 para compressão de coordenadas
static int cmp_ll(const void *a, const void *b) {
    long long va = *(const long long *)a;
    long long vb = *(const long long *)b;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
}

// Busca binária para obter o rank comprimido (1-based)
static int get_rank(const long long *vals, int m, long long val) {
    int low = 0, high = m - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (vals[mid] == val) return mid + 1;
        if (vals[mid] < val) low = mid + 1;
        else high = mid - 1;
    }
    return low + 1;
}

// Binary Indexed Tree (Fenwick Tree)
static void bit_update(int *bit, int n, int idx, int val) {
    for (; idx <= n; idx += idx & -idx) {
        bit[idx] += val;
    }
}

static int bit_query(const int *bit, int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int main(void) {
    int n;
    long long x1, x2;
    if (scanf("%d %lld %lld", &n, &x1, &x2) != 3) {
        return 0;
    }

    Line *lines = (Line *)malloc(sizeof(Line) * (size_t)n);
    long long *y2_vals = (long long *)malloc(sizeof(long long) * (size_t)n);

    for (int i = 0; i < n; i++) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        lines[i].y1 = a * x1 + b;
        lines[i].y2 = a * x2 + b;
        y2_vals[i] = lines[i].y2;
    }

    // Compressão de coordenadas para os valores de y2
    qsort(y2_vals, (size_t)n, sizeof(long long), cmp_ll);
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || y2_vals[i] != y2_vals[i - 1]) {
            y2_vals[m++] = y2_vals[i];
        }
    }

    for (int i = 0; i < n; i++) {
        lines[i].rank2 = get_rank(y2_vals, m, lines[i].y2);
    }

    // Ordenar as retas: y1 ascendente, y2 descendente
    qsort(lines, (size_t)n, sizeof(Line), cmp_lines);

    // Contar pares com y1_i < y1_j e y2_i < y2_j usando Fenwick Tree
    int *bit = (int *)calloc((size_t)(m + 1), sizeof(int));
    long long non_intersecting = 0;

    for (int i = 0; i < n; i++) {
        // Consultar quantos elementos inseridos têm y2 estritamente menor
        non_intersecting += bit_query(bit, lines[i].rank2 - 1);
        bit_update(bit, m, lines[i].rank2, 1);
    }

    long long total_pairs = (long long)n * (n - 1) / 2;
    long long ans = total_pairs - non_intersecting;

    printf("%lld\n", ans);

    free(lines);
    free(y2_vals);
    free(bit);

    return 0;
}
```

